mapper.select:
select  from sys_plant p
p.use_yn = #{useYn}
order by p.sort_no, p.plant_cd

mapper.update:
update sys_plant set plant_nm = #{f.plantNm}, addr = #{f.addr}, time_zone = #{f.timeZone}, sort_no = #{f.sortNo},
                     use_yn = #{f.useYn}, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where plant_cd = #{f.plantCd} and row_ver = #{f.rowVer}

mapper.select:
select , 0 as lvl,
       (select count(*) from mst_equip_hier c where c.parent_id = n.node_id) as child_cnt
  from mst_equip_hier n where n.node_id = #{nodeId}

mapper.update:
update mst_equip_hier
   set parent_id = #{f.parentId}, node_cd = #{f.nodeCd}, node_nm = #{f.nodeNm}, sort_no = #{f.sortNo},
       use_yn = #{f.useYn}, remark = #{f.remark}, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where node_id = #{id} and row_ver = #{f.rowVer}
